mapper.select:
SELECT /* LGVPAY00031.retrievePaidLeaveEmpList */ tpp.paid_leave_id , tpp.payment_yyyymm , tpp.paid_leave_detail_code , tpp.employee_no , em.full_name_english AS employee_name , em.full_name_local AS employee_name_local , TO_CHAR(tpp.start_date, 'DD/MM/YYYY') AS start_date , TO_CHAR(tpp.end_date , 'DD/MM/YYYY') AS end_date , tpp.end_date - tpp.start_date + 1 AS calendar_days , ( SELECT COUNT(*) FROM tb_att_result_n tar WHERE tar.employee_no = tpp.employee_no AND tar.time_and_attendance_date BETWEEN tpp.start_date AND tpp.end_date AND tar.time_and_attendance_code = 'PL' AND tar.time_attend_detail_code = tpp.paid_leave_detail_code ) AS att_applied_days , tpp.note , em.org_name_local AS organization_name , em.assignment_category AS emp_category_code , DECODE(em.assignment_category, 'LGD_OW', 'OW', 'LGD_LW', 'LW', em.assignment_category) AS emp_category_name , (SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , em.grade AS grade_code , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') AS date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') AS date_retire FROM tb_pay_paid_leave_n tpp , emp_master em WHERE em.employee_number = tpp.employee_no AND tpp.payment_yyyymm = #{payMonth} AND tpp.paid_leave_detail_code = #{paidLeaveDetailCode}
AND tpp.employee_no = #{employeeNo}
AND ( UPPER(em.full_name_local) LIKE '%' || UPPER(#{employeeName}) || '%' OR UPPER(em.full_name_english) LIKE '%' || UPPER(#{employeeName}) || '%' )
ORDER BY tpp.employee_no, tpp.start_date

SELECT /* LGVPAY00031.retrieveOverlapCount */
       COUNT(*) AS overlap_cnt
FROM   tb_pay_paid_leave_n tpp
WHERE  tpp.employee_no            = #{employeeNo}
AND    tpp.paid_leave_detail_code = #{paidLeaveDetailCode}
AND    tpp.start_date            <= TO_DATE(#{endDate}  , 'DD/MM/YYYY')
AND    tpp.end_date              >= TO_DATE(#{startDate}, 'DD/MM/YYYY')

AND    tpp.paid_leave_id         != #{paidLeaveId}

mapper.insert:
INSERT /* LGVPAY00031.insertPaidLeaveEmp */ INTO tb_pay_paid_leave_n
      ( paid_leave_id
      , payment_yyyymm
      , paid_leave_detail_code
      , employee_no
      , start_date
      , end_date
      , note
      , creation_user_id
      , creation_date
      )
VALUES( sq_pay_paid_leave_id.NEXTVAL
      , #{payMonth}
      , #{paidLeaveDetailCode}
      , #{employeeNo}
      , TO_DATE(#{startDate}, 'DD/MM/YYYY')
      , TO_DATE(#{endDate}  , 'DD/MM/YYYY')
      , #{note}
      , #{applicationUserId}
      , SYSDATE
      )

mapper.delete:
DELETE /* LGVPAY00031.deletePaidLeaveEmp */
FROM   tb_pay_paid_leave_n
WHERE  paid_leave_id = #{paidLeaveId}

DELETE /* LGVPAY00031.deleteAllPaidLeaveInMonth */
FROM   tb_pay_paid_leave_n
WHERE  payment_yyyymm         = #{payMonth}
AND    paid_leave_detail_code = #{paidLeaveDetailCode}

mapper.insert:
INSERT INTO /* LGVPAY00031.createExcelDownloadData */ XXLGE_EXPORT_INFO ( SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8 , ATTRIBUTE9, ATTRIBUTE10, ATTRIBUTE11, ATTRIBUTE12 ) SELECT AA.* FROM ( SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 1 AS ORDER_BY , 'KO16KSC5601' , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME , 'Start Date (DD/MM/YYYY)' AS START_DATE , 'End Date (DD/MM/YYYY)' AS END_DATE , 'Note' AS NOTE , 'Paid Leave Type' AS PAID_LEAVE_DETAIL_CODE , 'Month' AS PAYMENT_YYYYMM , 'Applied T&A Days' AS ATT_APPLIED_DAYS , 'Organization Name' AS ORGANIZATION_NAME , 'Emp. Category' AS EMP_CATEGORY_NAME , 'Hire Date' AS DATE_HIRE_SUBSIDIARY , 'Resignation Date' AS DATE_RETIRE FROM DUAL UNION ALL SELECT #{sessionId} , #{USER_SESSION.applicationUserId} , SYSDATE , 2 AS ORDER_BY , 'KO16KSC5601' , tpp.employee_no , em.full_name_english , TO_CHAR(tpp.start_date, 'DD/MM/YYYY') , TO_CHAR(tpp.end_date , 'DD/MM/YYYY') , tpp.note , tpp.paid_leave_detail_code , tpp.payment_yyyymm , TO_CHAR(( SELECT COUNT(*) FROM tb_att_result_n tar WHERE tar.employee_no = tpp.employee_no AND tar.time_and_attendance_date BETWEEN tpp.start_date AND tpp.end_date AND tar.time_and_attendance_code = 'PL' AND tar.time_attend_detail_code = tpp.paid_leave_detail_code )) , em.org_name_local , DECODE(em.assignment_category, 'LGD_OW', 'OW', 'LGD_LW', 'LW', em.assignment_category) , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') , TO_CHAR(em.date_retire, 'DD/MM/YYYY') FROM tb_pay_paid_leave_n tpp , emp_master em WHERE em.employee_number = tpp.employee_no AND tpp.payment_yyyymm = #{payMonth} AND tpp.paid_leave_detail_code = #{paidLeaveDetailCode}
AND tpp.employee_no = #{employeeNo}
AND ( UPPER(em.full_name_local) LIKE '%' || UPPER(#{employeeName}) || '%' OR UPPER(em.full_name_english) LIKE '%' || UPPER(#{employeeName}) || '%' )
) AA ORDER BY AA.ORDER_BY, AA.EMPLOYEE_NO
